// Every operation has to be O(1). Scanning for the least recently used entry,
// or re-sorting on each touch, will not finish this.
func TestLRUIsConstantTime(t *testing.T) {
	const size = 50000
	c := NewLRUCache(size)
	for i := 0; i < size; i++ {
		c.Put(i, i)
	}
	for round := 0; round < 4; round++ {
		for i := 0; i < size; i++ {
			if got := c.Get(i); got != i {
				t.Fatalf("Get(%d) = %d, want %d", i, got, i)
			}
		}
	}
	for i := size; i < 2*size; i++ {
		c.Put(i, i)
	}
	if got := c.Get(0); got != -1 {
		t.Fatalf("Get(0) = %d, want -1 after the cache turned over completely", got)
	}
	if got := c.Get(2*size - 1); got != 2*size-1 {
		t.Fatalf("Get(%d) = %d, want %d", 2*size-1, got, 2*size-1)
	}
}

