func countPrimes(n int) int {
	if n < 3 {
		return 0
	}
	composite := make([]bool, n)
	for p := 2; p*p < n; p++ {
		if composite[p] {
			continue
		}
		for m := p * p; m < n; m += p {
			composite[m] = true
		}
	}
	count := 0
	for p := 2; p < n; p++ {
		if !composite[p] {
			count++
		}
	}
	return count
}
